<?php
require __DIR__ . '/app.php';
if (logged_in()) { header('Location: index.php'); exit; }
$error=''; $success=false;
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $id=trim($_POST['student_id']??''); $name=trim($_POST['name']??''); $last=trim($_POST['lastname']??''); $dept=trim($_POST['department']??''); $pass=$_POST['password']??''; $repeat=$_POST['repeat_password']??'';
    if (!preg_match('/^[0-9A-Za-z-]{4,32}$/',$id) || $name==='' || $last==='' || $dept==='') $error='กรุณากรอกข้อมูลให้ครบถ้วนและตรวจสอบรหัสนักศึกษา';
    elseif (strlen($pass)<8) $error='รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร'; elseif ($pass!==$repeat) $error='รหัสผ่านยืนยันไม่ตรงกัน';
    else try { $hash=password_hash($pass,PASSWORD_DEFAULT); $stmt=db()->prepare("INSERT INTO users(student_id,name,lastname,department,password,role) VALUES(?,?,?,?,?,'user')"); $stmt->bind_param('sssss',$id,$name,$last,$dept,$hash); $stmt->execute(); $stmt->close(); $success=true; } catch(Throwable $e) { $error='สมัครไม่สำเร็จ รหัสนักศึกษานี้อาจมีในระบบแล้ว'; }
}
page_head('สมัครสมาชิก'); ?>
<section class="auth-layout"><div class="auth-aside"><p class="eyebrow">CREATE YOUR ACCOUNT</p><h1>พร้อมรับ<br>การดูแลจากทีม IT</h1><p>สร้างบัญชีด้วยรหัสนักศึกษา เพื่อแจ้งซ่อมและติดตามสถานะได้สะดวก</p><div class="auth-deco">RIETC <b>CARE</b><span>IT SUPPORT PORTAL</span></div></div><div class="auth-card register-card"><div class="auth-heading"><div class="step-icon">＋</div><div><p class="eyebrow">GET STARTED</p><h2>สมัครสมาชิก</h2></div></div><?php if($error): ?><div class="alert"><?=e($error)?></div><?php endif; ?><?php if($success): ?><div class="success-box"><b>สมัครสมาชิกสำเร็จ</b><p>เข้าสู่ระบบเพื่อเริ่มแจ้งซ่อมได้เลย</p><a class="button full" href="login.php">ไปหน้าเข้าสู่ระบบ →</a></div><?php else: ?><form method="post" class="form-stack"><?=csrf_field()?><label>รหัสนักศึกษา<input name="student_id" required maxlength="32" value="<?=e($_POST['student_id']??'')?>" placeholder="เช่น 66209010001"></label><div class="two-col"><label>ชื่อ<input name="name" required value="<?=e($_POST['name']??'')?>"></label><label>นามสกุล<input name="lastname" required value="<?=e($_POST['lastname']??'')?>"></label></div><label>สาขาวิชา<select name="department" required><option value="">เลือกสาขาวิชา</option><?php foreach(['Information Technology'=>'เทคโนโลยีสารสนเทศ (IT)','Computer Science'=>'วิทยาการคอมพิวเตอร์','Electronics'=>'อิเล็กทรอนิกส์','Other'=>'อื่น ๆ'] as $v=>$l): ?><option value="<?=e($v)?>" <?=($_POST['department']??'')===$v?'selected':''?>><?=e($l)?></option><?php endforeach; ?></select></label><div class="two-col"><label>รหัสผ่าน<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label>ยืนยันรหัสผ่าน<input type="password" name="repeat_password" required minlength="8" autocomplete="new-password"></label></div><button class="button full">สร้างบัญชี <span>→</span></button></form><p class="form-foot">มีบัญชีแล้ว? <a href="login.php">เข้าสู่ระบบ</a></p><?php endif; ?></div></section>
<?php page_foot(); ?>
